(function () {
  var STORAGE_KEY = 'todos-javascript';
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  var todos = [];
  var filter = 'all';
  var editingId = null;

  var newTodo = document.querySelector('.new-todo');
  var todoList = document.querySelector('.todo-list');
  var main = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var toggleAll = document.getElementById('toggle-all');
  var clearCompleted = document.querySelector('.clear-completed');
  var todoCount = document.querySelector('.todo-count');
  var filters = document.querySelectorAll('.filters a');

  function loadTodos() {
    try {
      var data = localStorage.getItem(STORAGE_KEY);
      if (data) { todos = JSON.parse(data); }
    } catch (e) { todos = []; }
  }

  function saveTodos() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function getFilter() {
    var hash = location.hash || '#/';
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    return 'all';
  }

  function filteredTodos() {
    var f = getFilter();
    if (f === 'active') return todos.filter(function (t) { return !t.completed; });
    if (f === 'completed') return todos.filter(function (t) { return t.completed; });
    return todos;
  }

  function activeCount() {
    return todos.filter(function (t) { return !t.completed; }).length;
  }

  function completedCount() {
    return todos.filter(function (t) { return t.completed; }).length;
  }

