  });
  refs.forEach(function (el, i) {
    var id = ids[i];
    // If the item no longer exists in the rendered list (deleted), skip — only check remaining items
    if (!currentIds[id]) return;
    if (!el || !el.parentNode) {
      throw new Error('Stored reference ' + i + ' (id=' + id + ') is not attached to the DOM');
